import fs from 'node:fs';

const accent = new Set(['#204f43', '#123c31', '#075985', '#064664', '#0891b2', '#08789b', '#0e7490', '#026aa2', '#065986', '#7a8c64', '#56774f', '#739356', '#738c61', '#587b40', '#537846', '#456c3a', '#56734b', '#425e35', '#b38950', '#8a6132', '#b27632', '#91ac77', '#6c8b54', '#8a9d6e', '#bf9a5f']);
const ink = new Set(['#163e35', '#172033', '#101828', '#1d2939', '#344054', '#294e3e', '#415f50']);
const success = new Set(['#027a48', '#067647', '#05603a']);
const danger = new Set(['#b42318', '#912018', '#d92d20']);
function recolor(source, publicSite) {
  return source.replace(/([\w-]+):\s*([^;{}]+)(?=[;}])/g, (declaration, property, value) => {
    if (property.startsWith('--')) return declaration;
    const colors = /#[\da-f]{3,8}\b|rgba?\([^)]+\)/gi;
    const changed = value.replace(colors, (raw) => {
      const color = raw.toLowerCase();
      if (/shadow/.test(property)) return 'rgb(0 0 0 / .25)';
      if (/outline/.test(property)) return 'var(--primary)';
      if (/border/.test(property)) return accent.has(color) ? 'var(--primary)' : 'var(--line)';
      if (/background/.test(property)) {
        if (color === '#204f43' || color === '#123c31') return 'var(--primary)';
        if (color === '#fdfdf9' || color === '#f4f7f9' || color === '#f5f7f9') return 'var(--background)';
        if (color === '#ecfdf3') return 'var(--success-soft)';
        if (color === '#fef3f2') return 'var(--danger-soft)';
        if (color === '#fff6ed') return 'var(--warning-soft)';
        if (color === '#fff' || color === '#ffffff' || color === '#fdfef9') return 'var(--surface)';
        if (/^rgb\(255 255 255/.test(color)) return 'rgb(13 19 28 / .94)';
        if (/^rgb\(253 253 249/.test(color)) return 'rgb(5 7 10 / .96)';
        if (/^rgb\(15 23 42/.test(color)) return 'rgb(0 0 0 / .72)';
        if (/^rgb/.test(color)) return 'rgb(0 229 255 / .08)';
        return 'var(--surface-raised)';
      }
      if (property === 'color' || property === 'accent-color') {
        if (accent.has(color)) return 'var(--primary)';
        if (ink.has(color)) return 'var(--ink)';
        if (!publicSite && success.has(color)) return 'var(--success)';
        if (!publicSite && danger.has(color)) return 'var(--danger)';
        if (!publicSite && color === '#b54708') return 'var(--warning)';
        if (['#fff', '#ffffff'].includes(color) || /^rgb\(255 255 255/.test(color)) return 'var(--ink)';
        return 'var(--muted)';
      }
      return raw;
    });
    return `${property}: ${changed}`;
  });
}

const websitePath = 'src/website.css';
let website = recolor(fs.readFileSync(websitePath, 'utf8'), true);
website = website.replace(/--clinic-ink: #[\da-f]+; --clinic-green: #[\da-f]+; --clinic-muted: #[\da-f]+; --clinic-cream: #[\da-f]+;/, '--clinic-ink: var(--ink); --clinic-muted: var(--muted);');
website = website.replace('.clinic-button-dark { color: var(--ink);', '.clinic-button-dark { color: var(--on-primary);');
website = website.replace('.clinic-button-cream { color: var(--primary); background: var(--surface-raised);', '.clinic-button-cream { color: var(--on-primary); background: var(--primary);');
website = website.replace(".clinic-filter-tabs button[aria-pressed='true'] { border-color: var(--primary); color: var(--ink);", ".clinic-filter-tabs button[aria-pressed='true'] { border-color: var(--primary); color: var(--on-primary);");
website = website.replace('.clinic-brand .brand-mark { width: 41px; height: 41px; color: var(--muted);', '.clinic-brand .brand-mark { width: 41px; height: 41px; color: var(--on-primary);');
website = website.replace('.clinic-demo-line { display:', '.clinic-demo-line { display:');
// These panels use dark surfaces so cyan stays an accent rather than a wash.
website = website.replace(/(\.clinic-demo-line \{[^}]*background: )var\(--primary\)/, '$1var(--surface)');
website = website.replace(/(\.clinic-bottom-cta \{[^}]*background: )var\(--primary\)/, '$1var(--surface-raised)');
website = website.replace(/(\.clinic-button-dark:hover \{ background: )var\(--primary\)/, '$1var(--primary-dark)');
fs.writeFileSync(websitePath, website);

const portalPath = 'src/index.css';
const originalPortal = fs.readFileSync(portalPath, 'utf8');
const printIndex = originalPortal.indexOf('@media print');
let portal = recolor(originalPortal.slice(0, printIndex), false) + originalPortal.slice(printIndex);
portal = portal.replace('color: #172033;', 'color: var(--ink);');
portal = portal.replace(/--primary: #[\da-f]+;/, '--primary: #00e5ff;');
portal = portal.replace(/--primary-dark: #[\da-f]+;/, '--primary-dark: #69e2ef;');
portal = portal.replace(/--primary-soft: #[\da-f]+;/, '--primary-soft: #0b2630;');
portal = portal.replace(/--ink: #[\da-f]+;/, '--ink: #f5f7fa;');
portal = portal.replace(/--muted: #[\da-f]+;/, '--muted: #9baabd;');
portal = portal.replace(/--line: #[\da-f]+;/, '--line: #223042;');
portal = portal.replace(/--surface: #[\da-f]+;/, '--surface: #0d131c;\n  --background: #05070a;\n  --surface-raised: #111c29;\n  --on-primary: #05070a;\n  --success: #7ee2b5;\n  --success-soft: #0d281f;\n  --warning: #ffd28a;\n  --warning-soft: #302519;\n  --danger-soft: #2c151b;');
portal = portal.replace(/--danger: #[\da-f]+;/, '--danger: #ffb4b4;');
portal = portal.replace('text-rendering: optimizeLegibility;', 'text-rendering: optimizeLegibility;\n  color-scheme: dark;');
portal = portal.replace('.button-primary { color: var(--ink);', '.button-primary { color: var(--on-primary);');
portal = portal.replace('.brand-mark { display: grid;', '.brand-mark { display: grid;');
portal = portal.replace(/(\.brand-mark \{[^}]*color: )var\(--ink\)/, '$1var(--on-primary)');
portal = portal.replace(/(\.brand-mark \{[^}]*background: )[^;]+;/, '$1var(--primary);');
portal = portal.replace('color: white; background: var(--primary);', 'color: var(--on-primary); background: var(--primary);');
portal = portal.replace('.printable-report { color: black;', '.printable-report { --primary: #075985; --ink: #172033; --muted: #667085; --line: #d0d5dd; --surface: white; --surface-raised: #f8fafb; --background: white; --danger: #b42318; color-scheme: light; color: black; background: white;');
portal = portal.replace('.report-modal { position: static;', '.report-modal { background: white; position: static;');
fs.writeFileSync(portalPath, portal);

const illustrationPath = 'src/pages/website.tsx';
const illustrationColors = {
  '#e5e9dd': '#172332', '#bdcfc0': '#22364a', '#326d62': '#149aad', '#164f46': '#075366',
  '#faf4d9': '#abc7d8', '#d7e4d3': '#548397', '#f0efe3': '#142231', '#e3e5d8': '#101b28',
  '#b2c3b2': '#36576b', '#faf7e9': '#799ba9', '#9eb8a1': '#304d68', '#fff8da': '#63d8ed',
  '#9ba99c': '#05070a', '#674d35': '#273d52', '#397b6b': '#117e92', '#4a8c79': '#31b9c9',
  '#d7dcbe': '#a8c9d6', '#bcc5a6': '#688ea6', '#b3bdad': '#05070a', '#c59c79': '#5d7990',
  '#587a51': '#44778c', '#668b5e': '#4e9aaf', '#8a7457': '#4a6076', '#ae8963': '#50738b',
  '#c8aa83': '#668ba1', '#f3ead5': '#d8e8ef', '#f7f2df': '#c2d8e4', '#b9c8ae': '#48768a',
  '#d4b183': '#00e5ff', '#cbd5c4': '#2b4c62', '#d0d4c7': '#223b50', '#eff0df': '#b4cddc', '#668278': '#36576b',
};
fs.writeFileSync(illustrationPath, fs.readFileSync(illustrationPath, 'utf8').replace(/#[\da-f]{6}\b/gi, (color) => illustrationColors[color] || color));
const htmlPath = 'index.html';
fs.writeFileSync(htmlPath, fs.readFileSync(htmlPath, 'utf8').replace('content="#204f43"', 'content="#05070a"'));
